        modal.classList.add('open');
        modal.removeAttribute('hidden');
        // Focus first focusable element after transition
        setTimeout(function () {
          var els = getFocusable();
          if (els.length) els[0].focus();
        }, 260);
        document.addEventListener('keydown', trapFocus);
